ALTER TABLE public.legacy_carryover_snapshots ADD COLUMN state_hash text, ADD COLUMN backing_evidence jsonb;
ALTER TABLE public.reward_vault_v2_config ADD COLUMN verified_queue_enabled boolean NOT NULL DEFAULT false;
CREATE TABLE public.legacy_carryover_budgets(snapshot_id uuid PRIMARY KEY REFERENCES public.legacy_carryover_snapshots(id),verified_points bigint NOT NULL CHECK(verified_points>=0),goodwill_points bigint NOT NULL CHECK(goodwill_points>=0),actor_user_id uuid NOT NULL,approved_at timestamptz NOT NULL DEFAULT now(),evidence jsonb NOT NULL);
GRANT ALL ON public.legacy_carryover_budgets TO service_role;
ALTER TABLE public.legacy_carryover_budgets ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.guard_carryover_budget() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'carryover budget immutable'; END $$;
CREATE TRIGGER carryover_budget_immutable BEFORE UPDATE OR DELETE ON public.legacy_carryover_budgets FOR EACH ROW EXECUTE FUNCTION public.guard_carryover_budget();
CREATE FUNCTION public.carryover_admin(p_actor uuid,p_wallet text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE email text; BEGIN SELECT p.email INTO email FROM profiles p JOIN auth.users u ON u.id=p.id JOIN app_admins a ON lower(a.email)=lower(p.email) WHERE p.id=p_actor AND lower(p.wallet_address)=lower(p_wallet) AND a.role='super_admin' AND NOT coalesce(a.disabled,false) AND u.email_confirmed_at IS NOT NULL AND (u.banned_until IS NULL OR u.banned_until<now()); IF email IS NULL THEN RAISE EXCEPTION 'active authenticated bound Super Admin required'; END IF; RETURN email; END $$;
CREATE FUNCTION public.legacy_carryover_state_hash() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT encode(sha256(convert_to(jsonb_build_array((SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY id),'[]') FROM flow_points_ledger l),(SELECT coalesce(jsonb_agg(jsonb_build_array(id,lower(wallet_address)) ORDER BY id),'[]') FROM profiles),(SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY id),'[]') FROM reward_settlement_batches b),(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY id),'[]') FROM reward_payout_approvals a),(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY ledger_id),'[]') FROM reward_award_destinations d),(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY ledger_id),'[]') FROM reward_economic_award_allocations a),(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY batch_id),'[]') FROM reward_publish_attempts a),(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY batch_id),'[]') FROM reward_retired_drafts r),(SELECT coalesce(jsonb_agg(to_jsonb(v) ORDER BY activity_id),'[]') FROM verified_activities v),(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]') FROM reward_evidence_reviews r),(SELECT coalesce(jsonb_agg(to_jsonb(u) ORDER BY id),'[]') FROM (SELECT id,email_confirmed_at,banned_until FROM auth.users) u))::text,'UTF8')),'hex') $$;
CREATE FUNCTION public.legacy_carryover_preview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE result jsonb; state text;
BEGIN
 IF (SELECT count(*) FROM flow_points_ledger)>100000 THEN RAISE EXCEPTION 'complete carryover scan exceeds bound; no partial snapshot permitted'; END IF;
 state:=legacy_carryover_state_hash();
 WITH committed AS (SELECT wallet,sum(points) pts FROM (SELECT lower(x->>'account') wallet,(x->>'amount')::numeric/1e18 points FROM reward_settlement_batches b CROSS JOIN LATERAL jsonb_array_elements(b.leaves) x WHERE b.chain_id=677 AND (b.publication_verified_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM reward_retired_drafts r WHERE r.batch_id=b.id)) UNION ALL SELECT lower(wallet),points FROM reward_payout_approvals WHERE status IN('PROPOSED','APPROVED','CONFIRMED') AND settlement_batch_id IS NULL) c GROUP BY wallet), rows AS (
 SELECT l.*,lower(p.wallet_address) wallet,
 CASE WHEN l.program_id='SIGNUP_BONUS' AND l.reason IN('SIGNUP_BONUS_REFEREE','REFERRAL_SIGNUP_BONUS') AND l.funding_state='FUNDED' THEN true
 WHEN l.program_id='CORE_SWAP' AND l.chain_id=677 AND l.reason IN('CORE_SWAP','CORE_SWAP_V2') AND ((l.provenance_state='VERIFIED' AND EXISTS(SELECT 1 FROM verified_activities v WHERE v.activity_id=l.verified_activity_id AND v.status='CONFIRMED' AND v.source_chain_id=677 AND lower(v.source_tx_hash)=lower(l.tx_hash) AND v.source_log_index=l.source_log_index AND lower(v.user_wallet)=lower(l.wallet_address))) OR (l.provenance_state='EXCEPTION_APPROVED' AND EXISTS(SELECT 1 FROM reward_evidence_reviews r WHERE r.ledger_id=l.id AND r.points=l.points AND r.status='APPROVED' AND r.policy_id='HISTORICAL_PRICING_EXCEPTION_V1' AND r.decided_by IS NOT NULL AND r.decided_by<>r.proposed_by AND lower(r.decided_by_email)<>lower(r.proposed_by_email)))) THEN true
 WHEN l.program_id='REFERRAL_MILESTONE' AND EXISTS(SELECT 1 FROM referral_milestone_awards m WHERE m.referrer_id=l.user_id AND m.points=l.points AND 'milestone:'||m.referrer_id::text||':'||m.referee_id::text||':'||m.milestone=l.activity_key) THEN true ELSE false END verified,
 CASE WHEN EXISTS(SELECT 1 FROM reward_award_destinations d WHERE d.ledger_id=l.id) OR EXISTS(SELECT 1 FROM reward_economic_award_allocations a WHERE a.ledger_id=l.id) THEN 'EXCLUDED_ALREADY_V2'
 WHEN l.points<=0 OR (l.chain_id IS NOT NULL AND l.chain_id<>677) OR l.provenance_state='REJECTED' OR l.reason NOT IN('CORE_SWAP','CORE_SWAP_V2','SIGNUP_BONUS_REFEREE','REFERRAL_SIGNUP_BONUS','REFERRAL_FIRST_QUALIFYING_SWAP','REFERRAL_100_USD_VOLUME','REFERRAL_3_ACTIVE_DAYS','REFERRAL_SIGNUP') OR (l.activity_key IS NOT NULL AND EXISTS(SELECT 1 FROM flow_points_ledger q WHERE q.id<>l.id AND q.activity_key=l.activity_key)) OR (l.tx_hash IS NOT NULL AND EXISTS(SELECT 1 FROM flow_points_ledger q WHERE q.id<>l.id AND q.chain_id=l.chain_id AND lower(q.tx_hash)=lower(l.tx_hash) AND q.source_log_index IS NOT DISTINCT FROM l.source_log_index)) THEN 'EXCLUDED_NON_ECONOMIC'
 WHEN p.wallet_address IS NULL OR lower(p.wallet_address)!~'^0x[0-9a-f]{40}$' OR p.wallet_address='0x0000000000000000000000000000000000000000' OR (l.wallet_address IS NOT NULL AND lower(l.wallet_address)<>lower(p.wallet_address)) OR (SELECT count(*) FROM profiles q WHERE lower(q.wallet_address)=lower(p.wallet_address))<>1 OR u.email_confirmed_at IS NULL OR (u.banned_until IS NOT NULL AND u.banned_until>=now()) THEN 'NEEDS_IDENTITY' ELSE NULL END excluded
 FROM flow_points_ledger l LEFT JOIN profiles p ON p.id=l.user_id LEFT JOIN auth.users u ON u.id=l.user_id
 ), ordered AS (SELECT r.*,coalesce(c.pts,0) commitment,coalesce(sum(points) OVER(PARTITION BY r.wallet ORDER BY verified DESC,created_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) preceding FROM rows r LEFT JOIN committed c ON c.wallet=r.wallet WHERE excluded IS NULL), items AS (
 SELECT id,user_id,wallet,points,excluded bin,NULL::text source FROM rows WHERE excluded IS NOT NULL
 UNION ALL SELECT id,user_id,wallet,least(points,greatest(0,commitment-preceding))::integer,'EXCLUDED_PAID_V1',NULL FROM ordered WHERE commitment>preceding
 UNION ALL SELECT id,user_id,wallet,(points-least(points,greatest(0,commitment-preceding)))::integer,CASE WHEN verified THEN 'VERIFIED_UNPAID' ELSE 'GOODWILL_CANDIDATE' END,CASE WHEN verified THEN 'LEGACY_VERIFIED' ELSE 'OWNER_GOODWILL' END FROM ordered WHERE points>greatest(0,commitment-preceding)
 ), payload AS (SELECT coalesce(jsonb_agg(jsonb_build_object('ledgerId',id,'economicId','LEGACY_CARRYOVER_V2_20261108:'||id,'userId',user_id,'wallet',wallet,'points',points,'source',source) ORDER BY id) FILTER(WHERE source IS NOT NULL),'[]') awards,coalesce(sum(points) FILTER(WHERE source='LEGACY_VERIFIED'),0)::bigint verified,coalesce(sum(points) FILTER(WHERE source='OWNER_GOODWILL'),0)::bigint goodwill,count(DISTINCT wallet) FILTER(WHERE source IS NOT NULL) wallets FROM items)
 SELECT jsonb_build_object('items',awards,'verifiedPoints',verified,'goodwillPoints',goodwill,'wallets',wallets,'sourceCount',jsonb_array_length(awards),'stateHash',state,'snapshotHash','0x'||encode(sha256(convert_to(jsonb_build_array(state,awards)::text,'UTF8')),'hex'),'bins',(SELECT coalesce(jsonb_object_agg(bin,jsonb_build_object('rows',n,'points',pts)),'{}') FROM (SELECT bin,count(*) n,sum(points) pts FROM items GROUP BY bin) z)) INTO result FROM payload;
 RETURN result;
END $$;
CREATE OR REPLACE FUNCTION public.stage_legacy_carryover(p_hash text,p_items jsonb,p_summary jsonb) RETURNS uuid LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'use authenticated canonical snapshot staging'; END $$;
CREATE FUNCTION public.stage_legacy_carryover(p_hash text,p_actor uuid,p_wallet text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE preview jsonb; sid uuid; email text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('reward-destination-fence')); email:=carryover_admin(p_actor,p_wallet);
 IF EXISTS(SELECT 1 FROM legacy_carryover_snapshots WHERE status='CONFIRMED') THEN RAISE EXCEPTION 'carryover already confirmed'; END IF;
 preview:=legacy_carryover_preview(); IF p_hash IS DISTINCT FROM preview->>'snapshotHash' THEN RAISE EXCEPTION 'snapshot stale'; END IF;
 SELECT id INTO sid FROM legacy_carryover_snapshots WHERE snapshot_hash=p_hash; IF sid IS NOT NULL THEN RETURN sid; END IF;
 INSERT INTO legacy_carryover_snapshots(snapshot_hash,verified_points,goodwill_points,wallets,summary,state_hash) VALUES(p_hash,(preview->>'verifiedPoints')::bigint,(preview->>'goodwillPoints')::bigint,(preview->>'wallets')::int,preview-'items',preview->>'stateHash') RETURNING id INTO sid;
 INSERT INTO legacy_carryover_items SELECT sid,(x->>'ledgerId')::uuid,x->>'economicId',(x->>'userId')::uuid,x->>'wallet',(x->>'points')::int,x->>'source' FROM jsonb_array_elements(preview->'items') x;
 INSERT INTO admin_audit_events(actor_user_id,actor_email,actor_role,object_type,object_id,action,new_value) VALUES(p_actor,email,'super_admin','legacy_carryover',sid::text,'SNAPSHOT_STAGED',preview-'items'); RETURN sid;
END $$;
CREATE OR REPLACE FUNCTION public.confirm_legacy_carryover(p_snapshot uuid,p_hash text,p_verified bigint,p_goodwill_budget bigint,p_actor uuid,p_wallet text,p_free_wei numeric) RETURNS jsonb LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'fresh canonical deployment and commitment evidence required'; END $$;
CREATE FUNCTION public.confirm_legacy_carryover(p_snapshot uuid,p_hash text,p_verified bigint,p_goodwill_budget bigint,p_actor uuid,p_wallet text,p_free_wei numeric,p_evidence jsonb,p_observed timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s legacy_carryover_snapshots; c reward_vault_v2_config; preview jsonb; email text; pending numeric;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('reward-destination-fence')); email:=carryover_admin(p_actor,p_wallet);
 SELECT * INTO c FROM reward_vault_v2_config WHERE id FOR UPDATE; SELECT * INTO s FROM legacy_carryover_snapshots WHERE id=p_snapshot FOR UPDATE;
 IF s IS NULL OR s.status<>'DRAFT' OR EXISTS(SELECT 1 FROM legacy_carryover_snapshots WHERE status='CONFIRMED') THEN RAISE EXCEPTION 'carryover missing or already confirmed'; END IF;
 IF c IS NULL OR NOT c.financial_enabled OR NOT c.cutover_accepted OR NOT c.deployment_verified OR c.chain_id<>677 THEN RAISE EXCEPTION 'verified authorized Vault cutover required'; END IF;
 LOCK TABLE flow_points_ledger,profiles,reward_settlement_batches,reward_payout_approvals,reward_publish_attempts,reward_award_destinations,reward_economic_award_allocations IN SHARE ROW EXCLUSIVE MODE;
 preview:=legacy_carryover_preview();
 IF p_hash IS DISTINCT FROM s.snapshot_hash OR p_hash IS DISTINCT FROM preview->>'snapshotHash' OR s.state_hash IS DISTINCT FROM preview->>'stateHash' OR p_verified IS DISTINCT FROM s.verified_points OR p_goodwill_budget IS DISTINCT FROM s.goodwill_points THEN RAISE EXCEPTION 'exact snapshot or budget changed'; END IF;
 IF EXISTS(SELECT 1 FROM reward_publish_attempts WHERE phase<>'CONFIRMED_VERIFIED' AND NOT retry_safe) THEN RAISE EXCEPTION 'unresolved V1 publication'; END IF;
 IF p_observed IS NULL OR p_observed<now()-interval '30 seconds' OR p_observed>now()+interval '5 seconds' OR coalesce(p_evidence->>'verification','') NOT LIKE 'FROZEN_RUNTIME_CANONICAL_TOKEN_%' OR p_evidence->>'contract' IS DISTINCT FROM c.contract_address OR p_evidence->>'codeHash' IS DISTINCT FROM c.code_hash OR p_evidence->>'publisher' IS DISTINCT FROM c.publisher OR p_evidence->>'chainId' IS DISTINCT FROM '677' OR coalesce(p_evidence->>'blockHash','')!~'^0x[0-9a-f]{64}$' OR (p_evidence->>'freeWei')::numeric IS DISTINCT FROM p_free_wei OR (p_evidence->>'batchCapWei')::numeric IS DISTINCT FROM c.batch_cap_wei OR (p_evidence->>'dailyCapWei')::numeric IS DISTINCT FROM c.daily_cap_wei THEN RAISE EXCEPTION 'fresh exact frozen vault evidence required'; END IF;
 SELECT coalesce(sum(total_wei),0) INTO pending FROM reward_vault_v2_batches WHERE state<>'CREDITED';
 IF p_free_wei IS NULL OR p_free_wei<pending+(s.verified_points+s.goodwill_points)*1e18 THEN RAISE EXCEPTION 'full backing after existing V2 reservations required'; END IF;
 INSERT INTO legacy_carryover_budgets VALUES(s.id,p_verified,p_goodwill_budget,p_actor,now(),p_evidence);
 INSERT INTO reward_award_destinations(ledger_id,economic_award_id,destination,cutover_at) SELECT ledger_id,economic_id,'VAULT_V2',c.cutover_at FROM legacy_carryover_items WHERE snapshot_id=s.id;
 UPDATE legacy_carryover_snapshots SET status='CONFIRMED',goodwill_budget_points=p_goodwill_budget,confirmed_by=p_actor,confirmed_wallet=lower(p_wallet),confirmed_free_wei=p_free_wei,confirmed_at=now(),backing_evidence=p_evidence WHERE id=s.id;
 UPDATE reward_vault_v2_config SET verified_queue_enabled=true WHERE id;
 INSERT INTO admin_audit_events(actor_user_id,actor_email,actor_role,object_type,object_id,action,new_value,reason) VALUES(p_actor,email,'super_admin','legacy_carryover',s.id::text,'LEGACY_CARRYOVER_BUDGET_AND_QUEUE_APPROVED',jsonb_build_object('hash',s.snapshot_hash,'verified',p_verified,'goodwill',p_goodwill_budget,'wallets',s.wallets,'evidence',p_evidence),'One-time legacy budget; goodwill remains OWNER_GOODWILL; manual publisher only');
 RETURN jsonb_build_object('confirmed',true,'verified',p_verified,'goodwill',p_goodwill_budget,'wallets',s.wallets);
END $$;
-- Preserve strict existing future-award SQL; add an explicitly approved partial carryover source branch.
DO $migration$ DECLARE src text; def text; a integer; b integer;
BEGIN
 SELECT prosrc INTO src FROM pg_proc WHERE oid='public.vault_v2_source_rows_scan(uuid,uuid[],integer)'::regprocedure;
 src:=replace(src,'AND NOT EXISTS(SELECT 1 FROM reward_economic_award_allocations a WHERE a.ledger_id=l.id OR a.economic_award_id=d.economic_award_id)','');
 src:=split_part(src,' ORDER BY l.id LIMIT',1);
 src:=replace(src,'(p_after IS NULL OR l.id>p_after) AND (p_ids IS NULL OR l.id=ANY(p_ids))','(p_ids IS NULL OR l.id=ANY(p_ids))');
 EXECUTE 'CREATE FUNCTION public.vault_v2_canonical_sources(p_ids uuid[],p_allocated boolean) RETURNS TABLE(id uuid,user_id uuid,economic_award_id text,wallet text,points integer,program_id text,destination text,created_at timestamptz,policy_version text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $body$ SELECT * FROM ('||src||$branch$
 UNION ALL SELECT i.ledger_id,i.user_id,i.economic_id,i.wallet,i.points,i.source,'VAULT_V2',s.confirmed_at,s.policy FROM legacy_carryover_items i JOIN legacy_carryover_snapshots s ON s.id=i.snapshot_id AND s.status='CONFIRMED' JOIN legacy_carryover_budgets b ON b.snapshot_id=s.id AND b.verified_points=s.verified_points AND b.goodwill_points=s.goodwill_points JOIN reward_award_destinations d ON d.ledger_id=i.ledger_id AND d.economic_award_id=i.economic_id AND d.destination='VAULT_V2' JOIN profiles p ON p.id=i.user_id AND lower(p.wallet_address)=i.wallet JOIN auth.users u ON u.id=p.id AND u.email_confirmed_at IS NOT NULL AND (u.banned_until IS NULL OR u.banned_until<now()) JOIN flow_points_ledger l ON l.id=i.ledger_id AND l.user_id=i.user_id AND l.points>=i.points WHERE (p_ids IS NULL OR i.ledger_id=ANY(p_ids)) AND (SELECT count(*) FROM profiles q WHERE lower(q.wallet_address)=i.wallet)=1
 ) z WHERE p_allocated OR NOT EXISTS(SELECT 1 FROM reward_economic_award_allocations a WHERE a.ledger_id=z.id OR a.economic_award_id=z.economic_award_id) $body$ $branch$;
 SELECT pg_get_functiondef('public.reserve_vault_v2_new_awards(text,uuid[],text,text[],text[],numeric,text,jsonb,numeric,timestamptz,bigint,text)'::regprocedure) INTO def;
 def:=replace(def,'FOR s IN SELECT * FROM flow_points_ledger WHERE id=ANY(p_ids) LOOP','FOR s IN SELECT * FROM vault_v2_canonical_sources(p_ids,false) WHERE program_id NOT IN (''LEGACY_VERIFIED'',''OWNER_GOODWILL'') LOOP');
 def:=replace(def,'s.wallet_address','s.wallet');
 def:=replace(def,'SELECT lower(wallet_address) w,sum(points)::numeric*1e18 a FROM flow_points_ledger WHERE id=ANY(p_ids) GROUP BY lower(wallet_address)','SELECT wallet w,sum(points)::numeric*1e18 a FROM vault_v2_canonical_sources(p_ids,false) GROUP BY wallet');
 def:=replace(def,'SELECT l.id,d.economic_award_id,l.user_id,lower(l.wallet_address),l.program_id,l.points,''VAULT_V2'',p_batch FROM flow_points_ledger l JOIN reward_award_destinations d ON d.ledger_id=l.id WHERE l.id=ANY(p_ids)','SELECT id,economic_award_id,user_id,wallet,program_id,points,''VAULT_V2'',p_batch FROM vault_v2_canonical_sources(p_ids,false)');
 EXECUTE def;
 SELECT pg_get_functiondef('public.acquire_vault_v2_signing(text,uuid,text,bigint,bigint,text,text,numeric,numeric,timestamptz)'::regprocedure) INTO def;
 a:=strpos(def,' IF (SELECT count(*) FROM reward_economic_award_allocations'); b:=strpos(def,' INSERT INTO reward_vault_v2_signing_attempts');
 IF a=0 OR b=0 THEN RAISE EXCEPTION 'unexpected publisher definition'; END IF;
 def:=substr(def,1,a-1)||' IF (SELECT count(*) FROM reward_economic_award_allocations a JOIN vault_v2_canonical_sources(b.source_ids,true) s ON s.id=a.ledger_id AND s.economic_award_id=a.economic_award_id AND s.points=a.points AND s.user_id=a.user_id AND s.wallet=a.wallet AND s.program_id=a.program_id WHERE a.vault_batch_id=p_batch AND a.destination=''VAULT_V2'')<>cardinality(b.source_ids) THEN RAISE EXCEPTION ''award fence funding or binding changed''; END IF;'||chr(10)||substr(def,b);
 EXECUTE def;
END $migration$;
CREATE OR REPLACE FUNCTION public.vault_v2_source_rows_scan(p_after uuid,p_ids uuid[],p_limit integer) RETURNS TABLE(id uuid,user_id uuid,economic_award_id text,wallet text,points integer,program_id text,destination text,created_at timestamptz,policy_version text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT * FROM vault_v2_canonical_sources(p_ids,false) s WHERE p_after IS NULL OR s.id>p_after ORDER BY id LIMIT least(greatest(coalesce(p_limit,500),1),1000) $$;
CREATE OR REPLACE FUNCTION public.vault_v2_source_summary() RETURNS TABLE(source_count bigint,source_points bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*),coalesce(sum(points),0)::bigint FROM vault_v2_canonical_sources(NULL,false) $$;
CREATE OR REPLACE FUNCTION public.vault_v2_source_hash(p_ids uuid[]) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT encode(sha256(convert_to(coalesce(jsonb_agg(CASE WHEN i.ledger_id IS NULL THEN jsonb_build_array(to_jsonb(l),d.economic_award_id) ELSE jsonb_build_array(to_jsonb(l),d.economic_award_id,to_jsonb(i),to_jsonb(b)) END ORDER BY l.id),'[]')::text,'UTF8')),'hex') FROM flow_points_ledger l JOIN reward_award_destinations d ON d.ledger_id=l.id LEFT JOIN legacy_carryover_items i ON i.ledger_id=l.id AND EXISTS(SELECT 1 FROM legacy_carryover_snapshots s WHERE s.id=i.snapshot_id AND s.status='CONFIRMED') LEFT JOIN legacy_carryover_budgets b ON b.snapshot_id=i.snapshot_id WHERE l.id=ANY(p_ids) $$;
CREATE FUNCTION public.guard_carryover_v1_commitment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w text; BEGIN PERFORM pg_advisory_xact_lock(hashtext('reward-destination-fence')); IF NOT EXISTS(SELECT 1 FROM legacy_carryover_snapshots WHERE status='CONFIRMED') THEN RETURN NEW; END IF; IF TG_TABLE_NAME='reward_payout_approvals' THEN IF NEW.status NOT IN('PROPOSED','APPROVED','CONFIRMED') THEN RETURN NEW; END IF; IF TG_OP='UPDATE' AND NEW.wallet IS NOT DISTINCT FROM OLD.wallet AND NEW.points IS NOT DISTINCT FROM OLD.points THEN RETURN NEW; END IF; IF EXISTS(SELECT 1 FROM legacy_carryover_items i JOIN legacy_carryover_snapshots s ON s.id=i.snapshot_id AND s.status='CONFIRMED' WHERE i.wallet=lower(NEW.wallet)) THEN RAISE EXCEPTION 'wallet unpaid history carried to V2; no new V1 commitment'; END IF; ELSE IF TG_OP='UPDATE' AND NEW.leaves IS NOT DISTINCT FROM OLD.leaves THEN RETURN NEW; END IF; FOR w IN SELECT lower(x->>'account') FROM jsonb_array_elements(NEW.leaves) x LOOP IF EXISTS(SELECT 1 FROM legacy_carryover_items i JOIN legacy_carryover_snapshots s ON s.id=i.snapshot_id AND s.status='CONFIRMED' WHERE i.wallet=w) THEN RAISE EXCEPTION 'wallet unpaid history carried to V2; no new V1 batch'; END IF; END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER carryover_v1_approval_fence BEFORE INSERT OR UPDATE ON public.reward_payout_approvals FOR EACH ROW EXECUTE FUNCTION public.guard_carryover_v1_commitment();
CREATE TRIGGER carryover_v1_batch_fence BEFORE INSERT OR UPDATE ON public.reward_settlement_batches FOR EACH ROW EXECUTE FUNCTION public.guard_carryover_v1_commitment();
CREATE FUNCTION public.guard_confirmed_carryover_source() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM legacy_carryover_items i JOIN legacy_carryover_snapshots s ON s.id=i.snapshot_id AND s.status='CONFIRMED' WHERE i.ledger_id=OLD.id) THEN RAISE EXCEPTION 'confirmed carryover original source immutable'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE TRIGGER carryover_source_immutable BEFORE UPDATE OR DELETE ON public.flow_points_ledger FOR EACH ROW EXECUTE FUNCTION public.guard_confirmed_carryover_source();
CREATE OR REPLACE FUNCTION public.guard_legacy_carryover() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' OR TG_TABLE_NAME='legacy_carryover_items' THEN RAISE EXCEPTION 'legacy carryover snapshot immutable'; END IF; IF OLD.status='CONFIRMED' THEN RAISE EXCEPTION 'confirmed carryover immutable'; END IF; IF (to_jsonb(NEW)-ARRAY['status','goodwill_budget_points','confirmed_by','confirmed_wallet','confirmed_free_wei','confirmed_at','backing_evidence']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','goodwill_budget_points','confirmed_by','confirmed_wallet','confirmed_free_wei','confirmed_at','backing_evidence']) THEN RAISE EXCEPTION 'snapshot amounts immutable'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_vault_cutover_config() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' AND OLD.cutover_accepted THEN RAISE EXCEPTION 'cutover history immutable'; END IF; IF TG_OP='UPDATE' AND OLD.cutover_accepted THEN IF NEW.verified_queue_enabled IS DISTINCT FROM OLD.verified_queue_enabled AND NOT EXISTS(SELECT 1 FROM legacy_carryover_snapshots WHERE status='CONFIRMED') THEN RAISE EXCEPTION 'explicit carryover budget and queue approval required'; END IF; IF coalesce(current_setting('flowbridge.vault_settings_sync',true),'')='on' THEN IF (to_jsonb(NEW)-ARRAY['financial_enabled','updated_at','publisher','batch_cap_wei','daily_cap_wei','verified_queue_enabled']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['financial_enabled','updated_at','publisher','batch_cap_wei','daily_cap_wei','verified_queue_enabled']) THEN RAISE EXCEPTION 'only verified publisher/limits may change'; END IF; ELSIF (to_jsonb(NEW)-ARRAY['financial_enabled','updated_at','verified_queue_enabled']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['financial_enabled','updated_at','verified_queue_enabled']) THEN RAISE EXCEPTION 'accepted cutover identity immutable'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_carryover_budget(),public.carryover_admin(uuid,text),public.legacy_carryover_state_hash(),public.legacy_carryover_preview(),public.stage_legacy_carryover(text,uuid,text),public.confirm_legacy_carryover(uuid,text,bigint,bigint,uuid,text,numeric,jsonb,timestamptz),public.vault_v2_canonical_sources(uuid[],boolean),public.guard_carryover_v1_commitment(),public.guard_confirmed_carryover_source() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.guard_carryover_budget(),public.carryover_admin(uuid,text),public.legacy_carryover_state_hash(),public.legacy_carryover_preview(),public.stage_legacy_carryover(text,uuid,text),public.confirm_legacy_carryover(uuid,text,bigint,bigint,uuid,text,numeric,jsonb,timestamptz),public.vault_v2_canonical_sources(uuid[],boolean),public.guard_carryover_v1_commitment(),public.guard_confirmed_carryover_source() TO service_role;